// =====================================================================
// Décor des cartouches à thème (boosters) : dessins SVG du corps et de l'écran, calque d'éléments animés, animation d'ouverture.
// Les dix thèmes à décor reprennent les maquettes validées (Halloween, Saint-Nicolas, Fondue, Usine, Pâté, Saucisse,
// Pâté + saucisse, Raclette, Feux d'artifice, Gâteau d'anniversaire) ; leurs couleurs et animations sont dans boosters-styles.css.
// Tout est dessiné en SVG et CSS : aucun logo, nom de marque ni personnage protégé. Les calques décoratifs sont aria-hidden
// et ne reçoivent jamais le pointeur (.bs-over, .bs-fx).
// Utilisé par cartes.js (cartouches et scène d'ouverture) et admin-cards/boosters.js (miniatures).
// Animation d'ouverture (feux d'artifice, gâteau) : playOpeningFx, déclenchée par cartes.js à l'ouverture d'un booster de ces thèmes
// (environ 1,8 s, non bloquante) ; en mouvement réduit, un flash doux (API Web Animations, hors règles CSS).
// Exporte : themeDecor, openingFxKind, openingFxHtml, playOpeningFx.
// =====================================================================

/** Compteur pour des identifiants SVG uniques (dégradés, masques) : plusieurs cartouches peuvent être affichées ensemble. */
let uid = 0;

/** Une araignée (corps, deux groupes de pattes qui alternent, marque et yeux). */
const SPIDER_INNER = `<g class="bs-lg bs-la"><path d="M9 9 L5.5 5 L2 5.5 M9 11 L4.5 13 L1.5 15.5 M11 10 L15.5 8 L19 9 M11 11.8 L14.5 16 L16.5 19"/></g><g class="bs-lg bs-lb"><path d="M9 10 L4.5 8 L1 9 M9 11.8 L5.5 16 L3.5 19 M11 9 L14.5 5 L18 5.5 M11 11 L15.5 13 L18.5 15.5"/></g><ellipse class="bs-bd" cx="10" cy="13.2" rx="2.9" ry="3.8"/><circle class="bs-bd" cx="10" cy="8.6" r="2"/><path class="bs-mk" d="M10 11.6 L10.9 13.4 L10 15.2 L9.1 13.4 Z"/><circle class="bs-ey" cx="9.2" cy="7.9" r=".55"/><circle class="bs-ey" cx="10.8" cy="7.9" r=".55"/>`;
/**
 * HTML d'une araignée.
 * @param {number} size taille en px
 * @param {string} cls classes en plus de bs-sp (bs-or : araignée orange ; bs-dn : araignée pendue)
 * @param {string} [style] style en ligne
 */
const spider = (size, cls = '', style = '') => `<svg${style ? ` style="${style}"` : ''} class="bs-sp${cls}" width="${size}" height="${size}" viewBox="0 0 20 20" aria-hidden="true">${SPIDER_INNER}</svg>`;
/** Araignées pendues à un fil : [position gauche, classe de balancement, décalage, taille]. */
const HANGERS = [[28,"h0",-8,16],[172,"h1",-10,20],[196,"h2",-7.5,15]];
/** Araignées qui marchent : [classe de trajectoire, orange ?, taille]. */
const WALKERS = [["w0",false,24],["w1",true,20],["w2",false,22],["w3",false,17],["w4",false,26],["w5",true,19],["w6",false,21],["w7",false,16]];
/** Calque d'araignées de Halloween : trois pendues à leur fil, huit qui grouillent sur le label et les bords. */
function spiders() {
  const hung = HANGERS.map(([left, h, ml, size]) => `<span class="bs-hg" style="left:${left}px"><span class="bs-hd bs-${h}"><span class="bs-th"></span>${spider(size, ' bs-dn', `margin-left:${ml}px`)}</span></span>`).join('');
  const walk = WALKERS.map(([w, or, size]) => `<span class="bs-wk bs-${w}">${spider(size, or ? ' bs-or' : '')}</span>`).join('');
  return `<span class="bs-spl">${hung}${walk}</span>`;
}

/**
 * Décor par classe de style. body : SVG du corps (derrière l'étiquette) ; scr : SVG de l'écran (remplace le logo) ;
 * over : calque d'éléments au-dessus de la cartouche. Le signe § devient un suffixe unique dans les identifiants SVG.
 * @type {Record<string, {body: string, scr: string, over: string}>}
 */
