/**
 * Décor d'un style de cartouche, avec des identifiants SVG uniques ; null si le style n'a pas de décor dessiné
 * (les cartouches de couleur et quatre thèmes simples gardent le logo à l'écran).
 * @param {string} cls classe de style (cart--theme-<slug>)
 * @returns {{body: string, scr: string, over: string}|null} body et scr : contenu des éléments .cart-body et .cart-scr ; over : calque à ajouter à la fin de la cartouche
 */
export function themeDecor(cls) {
  const d = DECOR[cls];
  if (!d) return null;
  const u = `-${++uid}`;
  const f = (s) => s.replaceAll('§', u);
  return { body: f(d.body), scr: f(d.scr), over: d.over ? `<span class="bs-over" aria-hidden="true">${f(d.over)}</span>` : '' };
}

/* ---------- Animation d'ouverture (feux d'artifice, gâteau) ---------- */
/** Thèmes qui ont une animation d'ouverture : classe de style -> sorte d'animation. */
const FX_KIND = { 'cart--theme-feux-artifice': 'feux', 'cart--theme-gateau-anniversaire': 'confettis' };
/**
 * Sorte d'animation d'ouverture d'un style.
 * @param {string} cls classe de style
 * @returns {'feux'|'confettis'|''} vide si le thème n'en a pas
 */
export const openingFxKind = (cls) => FX_KIND[cls] || '';

/** Bouquets de la scène d'ouverture (400 x 520, cartouche au centre) : [x, y, rayon, délai en s, deux couleurs]. */
const BURSTS = [
  [52, 214, 62, 0, '#ffffff', '#ffd34d'],
  [350, 176, 70, 0.15, '#ff9a3d', '#ff5fa2'],
  [104, 78, 66, 0.3, '#a98bff', '#4de3ff'],
  [312, 64, 60, 0.5, '#ffd34d', '#ffffff'],
  [200, 34, 56, 0.7, '#ff5fa2', '#ff9a3d'],
];
/** Couleurs des confettis. */
const CONFETTI = ['#ff5fa2', '#ffd23f', '#4de3ff', '#a98bff', '#7be08a', '#ff9a3d'];

/**
 * HTML du calque d'animation d'ouverture (aria-hidden, sans pointeur).
 * Feux : cinq bouquets de 16 étincelles autour de la cartouche. Confettis : 44 rectangles qui tournent en tombant.
 * Les positions sont calculées, pas tirées au hasard : le rendu est le même à chaque ouverture.
 * @param {'feux'|'confettis'} kind sorte d'animation
 * @returns {string}
 */
export function openingFxHtml(kind) {
  let inner = '';
  if (kind === 'feux') {
    for (const [x, y, r, t, c1, c2] of BURSTS) {
      let sparks = '';
      for (let k = 0; k < 16; k++) {
        const a = (k / 16) * Math.PI * 2 + t;
        const d = k % 2 ? r * 0.62 : r;
        sparks += `<i style="--x:${Math.round(Math.cos(a) * d)}px;--y:${Math.round(Math.sin(a) * d)}px;--c:${k % 2 ? c2 : c1};--t:${t}s"></i>`;
      }
      inner += `<span class="bs-bu" style="left:${x}px;top:${y}px;--t:${t}s"><b></b>${sparks}</span>`;
    }
  } else {
    let s = 7;
    /** Petit générateur déterministe (0 à 1). */
    const rnd = () => { s = (s * 16807) % 2147483647; return (s - 1) / 2147483646; };
    for (let k = 0; k < 44; k++) {
      const w = 6 + Math.round(rnd() * 8);
      inner += `<i class="bs-cf" style="--l:${(3 + rnd() * 94).toFixed(1)}%;--w:${w}px;--h:${Math.max(3, Math.round(w * (0.4 + rnd() * 0.3)))}px;--c:${CONFETTI[k % CONFETTI.length]};--t:${(rnd() * 0.55).toFixed(2)}s;--sx:${Math.round((rnd() - 0.5) * 70)}px"></i>`;
    }
  }
  return `<div class="bs-fx bs-fx--${kind}" data-fx-kind="${kind}" aria-hidden="true">${inner}</div>`;
}

/**
 * Joue l'animation d'ouverture du thème d'un booster, si le thème en a une. Ne bloque rien : le calque ne reçoit pas le pointeur
 * et se retire de lui-même (environ 2 s).
 * @param {HTMLElement|null} host scène d'ouverture (.op-stage) où poser le calque ; ignoré pour le flash doux
 * @param {string} cls classe de style du booster ouvert
 * @param {{soft?: boolean}} [o] soft : mouvement réduit, un flash doux (fondu de lumière sur la fenêtre) à la place de la scène
 * @returns {boolean} true si une animation a été lancée
 */
export function playOpeningFx(host, cls, { soft = false } = {}) {
  const kind = openingFxKind(cls);
  if (!kind) return false;
  if (soft) {
    const el = document.createElement('div');
    el.className = `bs-fx-soft bs-fx-soft--${kind}`;
    el.setAttribute('aria-hidden', 'true');
    document.body.append(el);
    const done = () => el.remove();
    if (typeof el.animate === 'function') {
      const a = el.animate([{ opacity: 0 }, { opacity: 1, offset: 0.35 }, { opacity: 0 }], { duration: 1600, easing: 'ease-in-out' });
      a.onfinish = done;
      a.oncancel = done;
    }
    setTimeout(done, 2200);
    return true;
  }
  if (!host) return false;
  host.querySelector('.bs-fx')?.remove();
  host.insertAdjacentHTML('beforeend', openingFxHtml(kind));
  const layer = host.lastElementChild;
  setTimeout(() => layer?.remove(), 2100);
  return true;
}
